// Author: Andres Ortiz
// Title: Ordered dithering workshop

/*
    *This is how to implement Ordered-dithering using a 2x2 bayer matrix

    *This is a 2x2 matrix containing the threshold values for the dither pattern

    *Pixels are sampled from the screen and converted to an index on the matrix

    *The value of the matrix's index is added to the luminance (brightness) 
     value at that pixel

    *If that pixel's luminance is brighter than the threshold value (0.5 but feel 
     free to experiment), the pixel is white, else the pixel becomes black
*/

//The matrix that we will be using in our dither function. 2x2 is the simplest matrix we can implement, but you can also do this with any matrix size so long as its a power of 2
mat4 bayer4x4 = mat4(vec4(0.00, 8.0, 2.0,  10.0), 
                     vec4(12.0, 4.0, 14.0, 6.0),
                     vec4(3.0,  11.0,1.0,  9.0),
                     vec4(15.0, 7.0, 13.0, 5.0));

float threshold = 0.50; //minimum value of lum to output white

float ditherStrength = 0.15; //strength of the dither effect

//this function will apply the dither to our image and smooth out the transitions between
//colors
float dither(vec3 color, float lum);

//calculates the current luminance (brightness of the pixel)
float getLum(vec3 color);

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    //refresher: uv-coordinates convert the current pixel of the screen to a value between 0 
    //and 1 we use this so our shaders work the same on all screen sizes
    vec2 uv = fragCoord/iResolution.xy;

    //our base color palette, a gradient between red and green depending on the current uv-coordinates
    vec3 color = texture(iChannel0, uv).rgb;

    //calculate the luminance (brightness) of the current pixel
    float lum = getLum(color);
    lum = dither(color, lum);

    //assign the current color of the pixel depending on the luminance (brightness)
    color = vec3(1.0 - step(lum, threshold));

    //output the color to the screen
    fragColor.rgb = color;

}

